	ep := mgr.lookupIPv4(ipv4)
	mgr.mutex.RUnlock()
	return ep
}

// LookupIPv6 looks up endpoint by IPv6 address
func (mgr *endpointManager) LookupIPv6(ipv6 string) *endpoint.Endpoint {
